            if "=" in a:
                k, v = a[2:].split("=", 1)
                flags[k] = v
            else:
                k = a[2:]
                if i + 1 < len(argv) and not argv[i + 1].startswith("-"):
                    flags[k] = argv[i + 1]
                    i += 1
                else:
                    flags[k] = True
